  [2200] = { name = "Back to Uldaman", instance = 70, level = 42, faction = "Alliance", prev = 2199, npc = "Talvash del Kissel", npcID = 6826, map = 1437, x = 14.8, y = 88.5, cont = 1415, cx = 48.3, cy = 51.37, objective = "Search for clues as to the current disposition of Talvash's necklace within Uldaman.  The slain paladin he mentioned was the person who had it last." }, -- Back to Uldaman
  [2201] = { name = "Find the Gems", instance = 70, level = 43, faction = "Alliance", prev = 2200, npc = "Remains of a Paladin", npcID = 6912, inside = true, objective = "Find the ruby, sapphire, and topaz that are scattered throughout Uldaman.  Once acquired, contact Talvash del Kissel remotely by using the Phial of Scrying he previously gave you.\n\nFrom the journal, you know...\n* The ruby has been stashed in a barricaded Shadowforge area.\n* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.\n\n* The sapphire has been claimed by Grimlok, the trogg leader.", npcs = { 4854 } }, -- Find the Gems
