  [3906] = { name = "Disharmony of Flame", level = 52, faction = "Horde", npc = "Thunderheart", npcID = 9084, map = 1427, x = 82.4, y = 39.7, cont = 1415, cx = 51.6, cy = 60.33, objective = "Travel to the quarry in Blackrock Mountain and slay Overmaster Pyron. Return to Thunderheart when you have completed this assignment." }, -- Disharmony of Flame
