  [3981] = { name = "Commander Gor'shak", instance = 230, level = 52, faction = "Horde", prev = 3906, npc = "Galamav the Marksman", npcID = 9081, map = 1427, x = 85.4, y = 39.1, cont = 1415, cx = 51.78, cy = 60.29, objective = "Find Commander Gor'shak in Blackrock Depths.\n\nYou recall that the crudely drawn picture of the orc included bars drawn over the portrait. Perhaps you should search for a prison of some sort." }, -- Commander Gor'shak
