  [4001] = { name = "What Is Going On?", instance = 230, level = 54, faction = "Horde", prev = 3982, npc = "Commander Gor'shak", npcID = 9020, inside = true, objective = "Speak with Kharan Mighthammer and gather information about Princess Moira Bronzebeard's kidnapping. Take that information to Thrall in Orgrimmar.\n\nYou recall Gor'shak mentioning that Kharan is being held in a cell nearby." }, -- What Is Going On?
