  [4023] = { name = "A Taste of Flame", level = 54, npc = "Cyrus Therepentous", npcID = 9459, map = 2548, x = 23.9, y = 36.5, cont = 1415, cx = 54.13, cy = 64.41, objective = "Show Cyrus Therepentous proof of your worth.\n\nYou have a feeling that Cyrus already knows that you are unworthy." }, -- A Taste of Flame
  [4024] = { name = "A Taste of Flame", instance = 230, level = 58, prev = 4023, npc = "Cyrus Therepentous", npcID = 9459, map = 2548, x = 23.9, y = 36.5, cont = 1415, cx = 54.13, cy = 64.41, choices = { 12066, 12082, 12083 }, objective = "Travel to Blackrock Depths and slay Bael'Gar.\n\nYou only know that the giant resides inside Blackrock Depths. Remember to use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence.\n\nReturn the Encased Fiery Essence to Cyrus Therepentous." }, -- A Taste of Flame
  [4061] = { name = "The Rise of the Machines", level = 54, faction = "Horde", npc = "Hierophant Theodora Mulvadania", npcID = 9079, map = 1427, x = 82.1, y = 39.1, cont = 1415, cx = 51.57, cy = 60.29, objective = "Venture to the Burning Steppes and recover 10 Fractured Elemental Shards for Hierophant Theodora Mulvadania.\n\nYou recall Theodora mentioning the golems and elementals of that region as being a source for these shards." }, -- The Rise of the Machines
  [4062] = { name = "The Rise of the Machines", level = 54, faction = "Horde", prev = 4061, npc = "Hierophant Theodora Mulvadania", npcID = 9079, map = 1427, x = 82.1, y = 39.1, cont = 1415, cx = 51.57, cy = 60.29, objective = "Take the Elemental Shard Sample to Lotwil Veriatus.\n\nYou recall Theodora saying that Lotwil was stationed in a camp to the east." }, -- The Rise of the Machines
  [4063] = { name = "The Rise of the Machines", instance = 230, level = 58, faction = "Horde", prev = 4062, npc = "Lotwil Veriatus", npcID = 2921, map = 1418, x = 25.9, y = 44.9, cont = 1415, cx = 53.2, cy = 60.09, choices = { 12109, 12110, 12108, 12111 }, objective = "Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic.", npcs = { 8905, 8906, 8907, 8908, 8983 } }, -- The Rise of the Machines
  [4081] = { name = "KILL ON SIGHT: Dark Iron Dwarves", instance = 230, level = 52, faction = "Horde", npc = "WANTED", map = 1427, x = 82.9, y = 38.7, cont = 1415, cx = 51.63, cy = 60.27, objective = "Venture to Blackrock Depths and destroy the vile aggressors!\n\nWarlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete.", npcs = { 8890, 8891, 8892 } }, -- KILL ON SIGHT: Dark Iron Dwarves
