  [4121] = { name = "Precarious Predicament", instance = 230, level = 58, faction = "Horde", prev = 4122, npc = "Grark Lorkrub", npcID = 9520, map = 1428, x = 40.2, y = 34.2, cont = 1415, cx = 49.56, cy = 64.63, objective = "Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge.\n\nYou recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody.\n\nYou will also be required to hand over your Thorium Shackles to Lexlort." }, -- Precarious Predicament
  [4122] = { name = "Grark Lorkrub", instance = 230, level = 58, faction = "Horde", npc = "Lexlort", npcID = 9080, map = 1427, x = 85.3, y = 39.0, cont = 1415, cx = 51.78, cy = 60.28, objective = "Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress.\n\nWhen you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody." }, -- Grark Lorkrub
