  [4742] = { name = "Seal of Ascension", instance = 229, level = 60, npc = "Vaelan", npcID = 10296, objective = "Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan.\n\nThe Generals, as told to you by Vaelan, are: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; and Overlord Wyrmthalak  of the Bloodaxe.", npcs = { 9045, 9097, 9098, 9196, 9197, 9198, 9199, 9200, 9201, 9216, 9217, 9218, 9219, 9236, 9237, 9239, 9240, 9241, 9257, 9258, 9259, 9260, 9261, 9262, 9263, 9264, 9265, 9266, 9267, 9268, 9269, 9568, 9583, 9596, 9692, 9693, 9716, 9717, 9718, 9736 } }, -- Seal of Ascension
  [4743] = { name = "Seal of Ascension", instance = 229, level = 60, prev = 4742, npc = "Vaelan", npcID = 10296, rewards = { 12344 }, objective = "Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake, Emberstrife and beat him without mercy until his will is broken.\n\nIt is at that moment which you must place the Unforged Seal of Ascension before the great beast. You must then be quick to use the Orb of Draconic Energy on his weakened form and claim dominion over his mental faculties. Control the beast and force the Flames of the Black Dragonflight upon the Unforged Seal of Ascension!" }, -- Seal of Ascension
