  [4862] = { name = "En-Ay-Es-Tee-Why", instance = 229, level = 59, npc = "Kibler", npcID = 10260, map = 1428, x = 65.9, y = 21.9, cont = 1415, cx = 51.7, cy = 63.6, rewards = { 12529 }, objective = "Travel to Blackrock Spire and collect 15 Spire Spider Eggs for Kibler.\n\nBy the sound of it, these eggs could be found near spiders." }, -- En-Ay-Es-Tee-Why
  [4866] = { name = "Mother's Milk", instance = 229, level = 60, npc = "Ragged John", npcID = 9563, map = 1428, x = 65.0, y = 23.8, cont = 1415, cx = 51.62, cy = 63.76, rewards = { 15873 }, objective = "In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Chances are good that you will have to kill her as well. Return to Ragged John when you are poisoned so that he can 'milk' you." }, -- Mother's Milk
  [4867] = { name = "Urok Doomhowl", instance = 229, level = 60, npc = "Warosh", npcID = 10799, inside = true, rewards = { 15867 }, objective = "Read Warosh's Scroll.  Bring Warosh's Mojo to Warosh." }, -- Urok Doomhowl
  [4903] = { name = "Warlord's Command", instance = 229, level = 60, faction = "Horde", inside = true, item = 12563, choices = { 13958, 13959, 13961, 13962, 13963 }, objective = "Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished.", npcs = { 9196, 9197, 9198, 9200, 9201, 9216, 9237, 9268, 9568, 9583 } }, -- Warlord's Command
