  [4941] = { name = "Eitrigg's Wisdom", level = 60, faction = "Horde", prev = 4903, npc = "Warlord Goretooth", npcID = 9077, map = 1427, x = 85.2, y = 38.8, cont = 1415, cx = 51.77, cy = 60.27, objective = "Speak with Eitrigg in Orgrimmar. When you have discussed matters with Eitrigg, seek council from Thrall.\n\nYou recall having seen Eitrigg in Thrall's chamber." }, -- Eitrigg's Wisdom
  [4974] = { name = "For The Horde!", instance = 229, level = 60, faction = "Horde", prev = 4941, npc = "Thrall", npcID = 4949, map = 1454, x = 31.7, y = 37.8, cont = 1414, cx = 57.59, cy = 44.35, choices = { 13966, 13968, 13965 }, objective = "Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar." }, -- For The Horde!
