  [4983] = { name = "Bijou's Reconnaissance Report", instance = 229, level = 59, faction = "Horde", prev = 4982, npc = "Bijou", npcID = 10257, inside = true, choices = { 15858, 15859 }, objective = "Take Bijou's Reconnaissance Report back to Grandmaster Lexlort in Kargath." }, -- Bijou's Reconnaissance Report
  [5001] = { name = "Bijou's Belongings", instance = 229, level = 59, faction = "Alliance", npc = "Bijou", npcID = 10257, inside = true, objective = "Find Bijou's Belongings and return them to her. Good luck!" }, -- Bijou's Belongings
