  [5047] = { name = "Finkle Einhorn, At Your Service!", instance = 229, level = 60, npc = "Finkle Einhorn", npcID = 10776, objective = "Talk to Malyfous Darkhammer in Everlook." }, -- Finkle Einhorn, At Your Service!
  [5063] = { name = "Cap of the Scarlet Savant", level = 60, prev = 5047, npc = "Malyfous's Catalogue", map = 1452, x = 61.0, y = 38.8, cont = 1414, cx = 59.01, cy = 24.88, rewards = { 12752 }, objective = "In order to create the Cap of the Scarlet Savant, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 5 Frayed Abomination Stitchings; 8 Arcane Crystals; 5 Enchanted Scarlet Thread. \n\nYou will also be required to pay 50 gold pieces for the crafting of the item." }, -- Cap of the Scarlet Savant
  [5065] = { name = "The Lost Tablets of Mosh'aru", level = 58, prev = 3528, npc = "Prospector Ironboot", npcID = 10460, map = 1446, x = 66.9, y = 24.0, cont = 1414, cx = 59.51, cy = 80.63, objective = "Bring the Third and Fourth Mosh'aru Tablets to Prospector Ironboot in Tanaris." }, -- The Lost Tablets of Mosh'aru
