  [5068] = { name = "Breastplate of Bloodthirst", level = 60, prev = 5047, npc = "Malyfous's Catalogue", map = 1452, x = 61.0, y = 38.8, cont = 1414, cx = 59.01, cy = 24.88, rewards = { 12757 }, objective = "In order to create the Breastplate of Bloodthirst, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 10 Frayed Abomination Stitchings; 5 Arcanite Bars; 5 Skin of Shadow.\n\nYou will also be required to pay 50 gold pieces for the crafting of the item." }, -- Breastplate of Bloodthirst
  [5081] = { name = "Maxwell's Mission", instance = 229, level = 60, faction = "Alliance", prev = 5002, npc = "Marshal Maxwell", npcID = 9560, map = 1428, x = 84.7, y = 69.0, cont = 1415, cx = 53.26, cy = 67.52, choices = { 13958, 13959, 13961, 13962, 13963 }, objective = "Travel to Blackrock Spire and destroy War Master Voone, Highlord Omokk, and Overlord Wyrmthalak. Return to Marshal Maxwell when the job is done.", npcs = { 9196, 9237, 9568 } }, -- Maxwell's Mission
