  [5126] = { name = "Lorax's Tale", level = 60, npc = "Lorax", npcID = 10918, map = 1452, x = 63.8, y = 73.8, cont = 1414, cx = 59.55, cy = 31.62, objective = "Speak with Lorax. Listen to what he has to say." }, -- Lorax's Tale
  [5127] = { name = "The Demon Forge", instance = 229, level = 60, prev = 5126, npc = "Lorax", npcID = 10918, map = 1452, x = 63.8, y = 73.8, cont = 1414, cx = 59.55, cy = 31.62, rewards = { 12696, 9224, 12849 }, objective = "Travel to Blackrock Spire and find Goraluk Anvilcrack. Slay him and then use the Blood Stained Pike upon his corpse. After his soul has been siphoned, the pike will be Soul Stained.\n\nYou must also find the Unforged Rune Covered Breastplate.\n\nReturn both the Soul Stained Pike and the Unforged Rune Covered Breastplate to Lorax in Winterspring." }, -- The Demon Forge
  [5160] = { name = "The Matron Protectorate", instance = 229, level = 60, npc = "Awbee", npcID = 10740, inside = true, objective = "Travel to Winterspring and find Haleh. Give her Awbee's scale." }, -- The Matron Protectorate
