  [5162] = { name = "Wrath of the Blue Flight", level = 60, prev = 5161, npc = "Haleh", npcID = 10929, map = 1452, x = 54.5, y = 51.2, cont = 1414, cx = 57.76, cy = 27.27, objective = "Speak with Jeziba in the Plaguelands. He resides in Andorhal." }, -- Wrath of the Blue Flight
