  [5166] = { name = "Breastplate of the Chromatic Flight", level = 60, prev = 5164, npc = "Catalogue of the Wayward", map = 1422, x = 39.3, y = 66.6, cont = 1415, cx = 49.08, cy = 25.61, rewards = { 12895 }, objective = "To forge the Breastplate of the Chromatic Flight, you will be required to bring the following items to Jeziba the 'Sculptor':\n\n1 Chromatic Carapace.\n\n10 Brilliant Chromatic Scales.\n\n10 Blood of Heroes.\n\n10 Frayed Abomination Stitchings.", npcs = { 10814 } }, -- Breastplate of the Chromatic Flight
  [5167] = { name = "Legplates of the Chromatic Defier", level = 60, prev = 5164, npc = "Catalogue of the Wayward", map = 1422, x = 39.3, y = 66.6, cont = 1415, cx = 49.08, cy = 25.61, choices = { 12903, 12945 }, objective = "To forge the Legplates of the Chromatic Defier, you will be required to bring the following items to Jeziba the 'Sculptor':\n\n1 Chromatic Carapace.\n\n10 Brilliant Chromatic Scales.\n\n10 Blood of Heroes.\n\n5 Skin of Shadow.", npcs = { 10814 } }, -- Legplates of the Chromatic Defier
  [5212] = { name = "The Flesh Does Not Lie", instance = 329, level = 60, npc = "Betina Bigglezink", npcID = 11035, map = 1423, x = 71.7, y = 49.9, cont = 1415, cx = 60.62, cy = 22.19, objective = "Recover 10 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample.", npcs = { 10381, 10382, 10405, 10406, 10407, 10412, 10413, 10414, 10416, 10417, 10435, 10436, 10437, 10440, 10463, 10516, 10558 } }, -- The Flesh Does Not Lie
  [5213] = { name = "The Active Agent", instance = 329, level = 60, prev = 5212, npc = "Betina Bigglezink", npcID = 11035, map = 1423, x = 71.7, y = 49.9, cont = 1415, cx = 60.62, cy = 22.19, choices = { 13209, 19812 }, objective = "Travel to Stratholme and search the ziggurats. Find and return new Scourge Data to Betina Bigglezink." }, -- The Active Agent
  [5214] = { name = "The Great Fras Siabi", instance = 329, level = 60, npc = "Smokey LaRue", npcID = 11033, map = 1423, x = 70.9, y = 48.4, cont = 1415, cx = 60.53, cy = 22.0, rewards = { 13171 }, objective = "Find Fras Siabi's smoke shop in Stratholme and recover a box of Siabi's Premium Tobacco. Return to Smokey LaRue when the job is done." }, -- The Great Fras Siabi
  [5243] = { name = "Houses of the Holy", instance = 329, level = 60, npc = "Leonid Barthalomew the Revered", npcID = 11036, map = 1423, x = 71.9, y = 48.3, cont = 1415, cx = 60.65, cy = 21.99, choices = { 13216, 13217 }, rewards = { 3928, 6149 }, objective = "Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid." }, -- Houses of the Holy
  [5251] = { name = "The Archivist", instance = 329, level = 60, npc = "Duke Nicholas Zverenhoff", npcID = 11039, map = 1423, x = 71.6, y = 50.1, cont = 1415, cx = 60.62, cy = 22.2, objective = "Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive.", npcs = { 10811 } }, -- The Archivist
  [5262] = { name = "The Truth Comes Crashing Down", instance = 329, level = 60, prev = 5251, inside = true, item = 13250, objective = "Take the Head of Balnazzar to Duke Nicholas Zverenhoff in the Eastern Plaguelands." }, -- The Truth Comes Crashing Down
  [5263] = { name = "Above and Beyond", instance = 329, level = 60, prev = 5262, npc = "Duke Nicholas Zverenhoff", npcID = 11039, map = 1423, x = 71.6, y = 50.1, cont = 1415, cx = 60.62, cy = 22.2, objective = "Venture to Stratholme and destroy Baron Rivendare. Take his head and return to Duke Nicholas Zverenhoff.", npcs = { 10440 } }, -- Above and Beyond
  [5264] = { name = "Lord Maxwell Tyrosus", level = 60, prev = 5263, npc = "Duke Nicholas Zverenhoff", npcID = 11039, map = 1423, x = 71.6, y = 50.1, cont = 1415, cx = 60.62, cy = 22.2, objective = "Speak with Lord Maxwell Tyrosus. He is inside the church." }, -- Lord Maxwell Tyrosus
  [5265] = { name = "The Argent Hold", level = 60, prev = 5264, npc = "Lord Maxwell Tyrosus", npcID = 11034, map = 1423, x = 71.9, y = 48.4, cont = 1415, cx = 60.65, cy = 22.0, choices = { 13246, 13243, 13249 }, objective = "Open the Argent Hold and claim your reward." }, -- The Argent Hold
  [5281] = { name = "The Restless Souls", level = 60, npc = "Caretaker Alen", npcID = 11038, map = 1423, x = 69.9, y = 53.7, cont = 1415, cx = 60.41, cy = 22.65, objective = "Find Egan. You only know that he was last seen around Stratholme." }, -- The Restless Souls
  [5282] = { name = "The Restless Souls", instance = 329, level = 60, prev = 5281, npc = "Egan", npcID = 11140, map = 1422, x = 73.5, y = 15.3, cont = 1415, cx = 53.25, cy = 19.34, rewards = { 13315 }, objective = "Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs!\n\nFree 15 Restless Souls and return to Egan." }, -- The Restless Souls
  [5341] = { name = "Barov Family Fortune", instance = 289, level = 60, faction = "Horde", npc = "Alexi Barov", npcID = 11022, map = 1422, x = 26.4, y = 58.8, cont = 1415, cx = 47.5, cy = 24.66, objective = "Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task." }, -- Barov Family Fortune
  [5342] = { name = "The Last Barov", level = 60, faction = "Horde", prev = 5341, npc = "Alexi Barov", npcID = 11022, map = 1422, x = 26.4, y = 58.8, cont = 1415, cx = 47.5, cy = 24.66, rewards = { 14022 }, objective = "Travel to Chillwind Camp - Alliance territory - and assassinate Weldon Barov. Take his head and return to Alexi Barov.\n\nBe warned, Weldon will probably be well protected by Alliance scum." }, -- The Last Barov
  [5343] = { name = "Barov Family Fortune", instance = 289, level = 60, faction = "Alliance", npc = "Weldon Barov", npcID = 11023, map = 1416, x = 79.8, y = 28.6, cont = 1415, cx = 49.58, cy = 27.7, objective = "Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task." }, -- Barov Family Fortune
  [5344] = { name = "The Last Barov", level = 60, faction = "Alliance", prev = 5343, npc = "Weldon Barov", npcID = 11023, map = 1416, x = 79.8, y = 28.6, cont = 1415, cx = 49.58, cy = 27.7, rewards = { 14023 }, objective = "Travel to the Bulwark - Horde territory - and assassinate Alexi Barov. Take his head and return to Weldon Barov.\n\nBe warned, Alexi will probably be well protected by Horde filth." }, -- The Last Barov
  [5382] = { name = "Doctor Theolen Krastinov, the Butcher", instance = 289, level = 60, npc = "Eva Sarkhoff", npcID = 11216, map = 1422, x = 70.2, y = 73.7, cont = 1415, cx = 52.85, cy = 26.48, objective = "Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete.", npcs = { 11261 } }, -- Doctor Theolen Krastinov, the Butcher
  [5384] = { name = "Kirtonos the Herald", instance = 289, level = 60, prev = 5515, npc = "Eva Sarkhoff", npcID = 11216, map = 1422, x = 70.2, y = 73.7, cont = 1415, cx = 52.85, cy = 26.48, choices = { 15805, 15806 }, rewards = { 13544 }, objective = "Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul.\n\nFight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff." }, -- Kirtonos the Herald
  [5461] = { name = "The Human, Ras Frostwhisper", level = 60, prev = 5384, npc = "Magistrate Marduke", npcID = 11286, map = 1422, x = 70.6, y = 74.1, cont = 1415, cx = 52.89, cy = 26.53, objective = "Travel to the Arathi Highlands, to the ruins of Stromgarde. Search Stromgarde for a Keepsake of Remembrance. If you find such an item, return with it to Magistrate Marduke." }, -- The Human, Ras Frostwhisper
  [5462] = { name = "The Dying, Ras Frostwhisper", level = 60, prev = 5461, npc = "Magistrate Marduke", npcID = 11286, map = 1422, x = 70.6, y = 74.1, cont = 1415, cx = 52.89, cy = 26.53, objective = "Travel to Light's Hope in Eastern Plaguelands and seek out Leonid Barthalomew the Revered. Show him the Keepsake of Remembrance and tell him all that you have discovered." }, -- The Dying, Ras Frostwhisper
  [5463] = { name = "Menethil's Gift", instance = 329, level = 60, prev = 5462, npc = "Leonid Barthalomew the Revered", npcID = 11036, map = 1423, x = 71.9, y = 48.3, cont = 1415, cx = 60.65, cy = 21.99, objective = "Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground." }, -- Menethil's Gift
  [5464] = { name = "Menethil's Gift", level = 60, prev = 5463, npc = "Menethil's Gift", objective = "Take the Soulbound Keepsake to Leonid Barthalomew in Eastern Plaguelands." }, -- Menethil's Gift
  [5465] = { name = "Soulbound Keepsake", level = 60, prev = 5464, npc = "Leonid Barthalomew the Revered", npcID = 11036, map = 1423, x = 71.9, y = 48.3, cont = 1415, cx = 60.65, cy = 21.99, objective = "Return to Magistrate Marduke in Caer Darrow. Show him the Soulbound Keepsake." }, -- Soulbound Keepsake
  [5466] = { name = "The Lich, Ras Frostwhisper", instance = 289, level = 60, prev = 5465, npc = "Magistrate Marduke", npcID = 11286, map = 1422, x = 70.6, y = 74.1, cont = 1415, cx = 52.89, cy = 26.53, choices = { 13982, 13986, 13984 }, rewards = { 14002 }, objective = "Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.", npcs = { 10508 } }, -- The Lich, Ras Frostwhisper
  [5515] = { name = "Krastinov's Bag of Horrors", instance = 289, level = 60, prev = 5382, npc = "Eva Sarkhoff", npcID = 11216, map = 1422, x = 70.2, y = 73.7, cont = 1415, cx = 52.85, cy = 26.48, objective = "Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff.", npcs = { 10503 } }, -- Krastinov's Bag of Horrors
  [5518] = { name = "The Gordok Ogre Suit", instance = 429, level = 60, npc = "Knot Thimblejack", npcID = 14338, inside = true, rewards = { 18258 }, objective = "Bring 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads, and Ogre Tannin to Knot Thimblejack.  He is currently chained inside the Gordok wing of Dire Maul.", npcs = { 11448, 11450, 13022 } }, -- The Gordok Ogre Suit
