  [5522] = { name = "Leonid Barthalomew", level = 60, prev = 4735, npc = "Tinkee Steamboil", npcID = 10267, map = 1428, x = 65.2, y = 24.0, cont = 1415, cx = 51.64, cy = 63.78, objective = "Bring the Frozen Eggs to Leonid Barthalomew in the Eastern Plaguelands." }, -- Leonid Barthalomew
