  [5542] = { name = "Demon Dogs", level = 56, npc = "Tirion Fordring", npcID = 1855, map = 1422, x = 67.3, y = 24.2, cont = 1415, cx = 52.5, cy = 20.43, objective = "Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete." }, -- Demon Dogs
