  [5725] = { name = "The Power to Destroy...", instance = 389, level = 16, faction = "Horde", npc = "Varimathras", npcID = 2425, map = 1416, x = 16.1, y = 11.4, cont = 1415, cx = 44.51, cy = 26.33, choices = { 15449, 15450, 15451 }, objective = "Bring the books Spells of Shadow and Incantations from the Nether to Varimathras in Undercity.", npcs = { 11322, 11324 } }, -- The Power to Destroy...
