  [5727] = { name = "Hidden Enemies", level = 12, faction = "Horde", prev = 5726, npc = "Thrall", npcID = 4949, map = 1454, x = 31.7, y = 37.8, cont = 1414, cx = 57.59, cy = 44.35, objective = "Take the Lieutenant's Insignia to Neeru Fireblade and speak to him. Gauge if he believes you are a member of the Burning Blade and then return to Thrall in Orgrimmar." }, -- Hidden Enemies
  [5728] = { name = "Hidden Enemies", instance = 389, level = 16, faction = "Horde", prev = 5727, npc = "Thrall", npcID = 4949, map = 1454, x = 31.7, y = 37.8, cont = 1414, cx = 57.59, cy = 44.35, objective = "Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar.", npcs = { 11518, 11519 } }, -- Hidden Enemies
  [5729] = { name = "Hidden Enemies", level = 15, faction = "Horde", prev = 5728, npc = "Thrall", npcID = 4949, map = 1454, x = 31.7, y = 37.8, cont = 1414, cx = 57.59, cy = 44.35, objective = "Speak to Neeru Fireblade in Orgrimmar." }, -- Hidden Enemies
