  [5761] = { name = "Slaying the Beast", instance = 389, level = 16, faction = "Horde", npc = "Neeru Fireblade", npcID = 3216, map = 1454, x = 49.5, y = 50.6, cont = 1414, cx = 58.26, cy = 44.83, objective = "Enter Ragefire Chasm and slay Taragaman the Hungerer, then bring his heart back to Neeru Fireblade in Orgrimmar.", npcs = { 11520 } }, -- Slaying the Beast
  [5781] = { name = "Of Forgotten Memories", level = 57, prev = 5742, npc = "Tirion Fordring", npcID = 1855, map = 1422, x = 67.3, y = 24.2, cont = 1415, cx = 52.5, cy = 20.43, objective = "Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective." }, -- Of Forgotten Memories
  [5845] = { name = "Of Lost Honor", level = 58, prev = 5781, npc = "Tirion Fordring", npcID = 1855, map = 1422, x = 67.3, y = 24.2, cont = 1415, cx = 52.5, cy = 20.43, objective = "Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective." }, -- Of Lost Honor
  [5846] = { name = "Of Love and Family", level = 58, prev = 5845, npc = "Tirion Fordring", npcID = 1855, map = 1422, x = 67.3, y = 24.2, cont = 1415, cx = 52.5, cy = 20.43, objective = "Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting." }, -- Of Love and Family
  [5848] = { name = "Of Love and Family", instance = 329, level = 60, prev = 5846, npc = "Artist Renfray", npcID = 11936, map = 1425, x = 21.7, y = 10.2, cont = 1415, cx = 52.31, cy = 26.68, objective = "Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world.\n\nReturn the painting to Tirion Fordring." }, -- Of Love and Family
  [5861] = { name = "Find Myranda", level = 60, prev = 5848, npc = "Tirion Fordring", npcID = 1855, map = 1422, x = 67.3, y = 24.2, cont = 1415, cx = 52.5, cy = 20.43, objective = "Travel to Uther's Tomb, located in the southern Plaguelands. Show Myranda the Hag Tirion's Gift." }, -- Find Myranda
  [5862] = { name = "Scarlet Subterfuge", level = 60, prev = 5861, npc = "Myranda the Hag", npcID = 11872, map = 1422, x = 50.8, y = 77.8, cont = 1415, cx = 50.48, cy = 26.98, objective = "Speak to Myranda to gain the Scarlet Illusion. Travel to Hearthglen while under the Scarlet Illusion and deliver Tirion's Gift to Highlord Taelan Fordring.\n\nHearthglen is to the north, Taelan should be inside of Mardenholde Keep." }, -- Scarlet Subterfuge
  [5944] = { name = "In Dreams", level = 60, prev = 5862, npc = "Highlord Taelan Fordring", npcID = 1842, map = 1422, x = 42.0, y = 14.8, cont = 1415, cx = 49.4, cy = 19.28, choices = { 15411, 15413, 15418, 15421, 16058 }, objective = "Escort Taelan Fordring out of Hearthglen." }, -- In Dreams
  [6133] = { name = "The Ranger Lord's Behest", level = 60, faction = "Horde", npc = "Nathanos Blightcaller", npcID = 11878, map = 1422, x = 84.4, y = 52.2, cont = 1415, cx = 54.58, cy = 23.85, objective = "Travel to the northern borders of the Eastern Plaguelands and recover the Quel'Thalas Registry. The item is somewhere in the Quel'Lithien lodge.\n\nYou must also slay 8 Rangers, 8 Pathstriders, and 8 Woodsmen." }, -- The Ranger Lord's Behest
  [6135] = { name = "Duskwing, Oh How I Hate Thee...", level = 60, faction = "Horde", prev = 6133, npc = "Nathanos Blightcaller", npcID = 11878, map = 1422, x = 84.4, y = 52.2, cont = 1415, cx = 54.58, cy = 23.85, choices = { 16994, 16995 }, objective = "Find Duskwing and slay him. From the corpse, recover a Patch of Duskwing's Fur and return it to Nathanos Blightcaller.\n\nIt is said that Duskwing roams the countryside to the north of Marris Stead." }, -- Duskwing, Oh How I Hate Thee...
  [6163] = { name = "Ramstein", instance = 329, level = 60, faction = "Horde", prev = 6135, npc = "Nathanos Blightcaller", npcID = 11878, map = 1422, x = 84.4, y = 52.2, cont = 1415, cx = 54.58, cy = 23.85, choices = { 18022, 17001 }, objective = "Travel to Stratholme and slay Ramstein the Gorger. Take his head as a souvenir for Nathanos." }, -- Ramstein
  [6402] = { name = "Stormwind Rendezvous", level = 60, faction = "Alliance", prev = 4322, npc = "Marshal Maxwell", npcID = 9560, map = 1428, x = 84.7, y = 69.0, cont = 1415, cx = 53.26, cy = 67.52, objective = "Travel to Stormwind City and venture to the city gates. Speak with Squire Rowe so that he may let Marshal Windsor know that you have arrived." }, -- Stormwind Rendezvous
  [6403] = { name = "The Great Masquerade", level = 60, faction = "Alliance", prev = 6402, npc = "Reginald Windsor", npcID = 12580, objective = "Follow Reginald Windsor through Stormwind. Protect him from harm!" }, -- The Great Masquerade
  [6501] = { name = "The Dragon's Eye", level = 60, faction = "Alliance", prev = 6403, npc = "Highlord Bolvar Fordragon", npcID = 1748, map = 1453, x = 80.2, y = 38.3, cont = 1415, cx = 44.52, cy = 67.78, objective = "You must search the world for a being capable of restoring the power to the Fragment of the Dragon's Eye. The only information you possess about such a being is that they exist." }, -- The Dragon's Eye
  [6502] = { name = "Drakefire Amulet", instance = 249, level = 60, faction = "Alliance", prev = 6501, npc = "Haleh", npcID = 10929, map = 1452, x = 54.5, y = 51.2, cont = 1414, cx = 57.76, cy = 27.27, rewards = { 16309 }, objective = "You must retrieve the Blood of the Black Dragon Champion from General Drakkisath. Drakkisath can be found in his throne room behind the Halls of Ascension in Blackrock Spire.", attunement = true }, -- Drakefire Amulet
