  [6569] = { name = "Oculus Illusions", instance = 229, level = 60, faction = "Horde", prev = 6568, npc = "Myranda the Hag", npcID = 11872, map = 1422, x = 50.8, y = 77.8, cont = 1415, cx = 50.48, cy = 26.98, objective = "Travel to Blackrock Spire and collect 20 Black Dragonspawn Eyes. Return to Myranda the Hag when the task is complete.", npcs = { 9096, 9568, 10083, 10366, 10371, 10372 } }, -- Oculus Illusions
  [6570] = { name = "Emberstrife", level = 60, faction = "Horde", prev = 6569, npc = "Myranda the Hag", npcID = 11872, map = 1422, x = 50.8, y = 77.8, cont = 1415, cx = 50.48, cy = 26.98, objective = "Travel to the Wyrmbog in Dustwallow Marsh and seek out Emberstrife's Den. Once inside, wear the Amulet of Draconic Subversion and speak with Emberstrife." }, -- Emberstrife
  [6582] = { name = "The Test of Skulls, Scryer", level = 60, faction = "Horde", prev = 6570, npc = "Emberstrife", npcID = 10321, map = 1441, x = 79.9, y = 38.8, cont = 1414, cx = 57.11, cy = 72.98, objective = "You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and return it to Emberstrife.\n\nYou know that Scryer can be found in Winterspring." }, -- The Test of Skulls, Scryer
  [6585] = { name = "The Test of Skulls, Axtroz", level = 60, faction = "Horde", prev = 6582, npc = "Emberstrife", npcID = 10321, map = 1441, x = 79.9, y = 38.8, cont = 1414, cx = 57.11, cy = 72.98, objective = "Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife." }, -- The Test of Skulls, Axtroz
  [6601] = { name = "Ascension...", level = 60, faction = "Horde", prev = 6585, npc = "Emberstrife", npcID = 10321, map = 1441, x = 79.9, y = 38.8, cont = 1414, cx = 57.11, cy = 72.98, objective = "It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rexxar and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next." }, -- Ascension...
  [6602] = { name = "Blood of the Black Dragon Champion", instance = 249, level = 60, faction = "Horde", prev = 6601, npc = "Rexxar", npcID = 10182, map = 1444, x = 46.4, y = 18.2, cont = 1414, cx = 40.35, cy = 65.27, rewards = { 16309 }, objective = "Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rexxar.", attunement = true }, -- Blood of the Black Dragon Champion
