  [6627] = { name = "Test of Lore", level = 30, faction = "Horde", prev = 1154, npc = "Braug Dimspirit", npcID = 4489, map = 1442, x = 78.8, y = 45.7, cont = 1414, cx = 48.01, cy = 46.35, objective = "Answer Braug Dimspirit's question successfully and then speak to him again. He will remain in Stonetalon Mountains when you are ready." }, -- Test of Lore
  [6628] = { name = "Test of Lore", level = 30, faction = "Horde", prev = 1160, npc = "Parqual Fintallas", npcID = 4488, map = 1458, x = 57.8, y = 65.4, cont = 1415, cx = 44.55, cy = 25.6, objective = "Answer Parqual Fintallas' question successfully and then speak to him again. He will remain in the Undercity until you are ready." }, -- Test of Lore
  [6921] = { name = "Amongst the Ruins", instance = 48, level = 27, faction = "Horde", npc = "Je'neu Sancrea", npcID = 12736, map = 1440, x = 11.6, y = 34.3, cont = 1414, cx = 43.57, cy = 38.5, objective = "Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale." }, -- Amongst the Ruins
