  [6981] = { name = "The Glowing Shard", instance = 43, level = 26, inside = true, item = 10441, objective = "Travel to Ratchet to find someone that can tell you more about the glowing shard.\n\nThen, deliver the shard as you are directed." }, -- The Glowing Shard
  [7028] = { name = "Twisted Evils", instance = 349, level = 47, npc = "Willow", npcID = 13656, map = 1443, x = 62.2, y = 39.6, cont = 1414, cx = 42.47, cy = 55.17, choices = { 17775, 17776, 17777, 17779 }, objective = "Collect 15 Theradric Crystal Carvings for Willow in Desolace.", npcs = { 11790, 11791, 11792, 11793, 11794, 12201, 12203, 12206, 12207, 12216, 12218, 12219, 12220, 12221, 12222, 12223, 12224, 12225, 12236, 12237, 12258, 13282, 13596, 13601 } }, -- Twisted Evils
  [7029] = { name = "Vyletongue Corruption", instance = 349, level = 47, faction = "Horde", npc = "Vark Battlescar", npcID = 11823, map = 1443, x = 23.2, y = 70.3, cont = 1414, cx = 37.71, cy = 58.93, choices = { 17768, 17778, 17770 }, objective = "Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.\n\nUse the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.\n\nHeal 8 plants by killing these Noxxious Scion, then return to Vark Battlescar in Shadowprey Village." }, -- Vyletongue Corruption
  [7041] = { name = "Vyletongue Corruption", instance = 349, level = 47, faction = "Alliance", npc = "Talendria", npcID = 11715, map = 1442, x = 42.8, y = 83.9, cont = 1414, cx = 43.24, cy = 51.42, choices = { 17768, 17778, 17770 }, objective = "Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.\n\nUse the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.\n\nHeal 8 plants by killing these Noxxious Scion, then return to Talendria in Nijel's Point." }, -- Vyletongue Corruption
  [7044] = { name = "Legends of Maraudon", instance = 349, level = 49, npc = "Cavindra", npcID = 13697, map = 1443, x = 32.1, y = 64.0, cont = 1414, cx = 38.79, cy = 58.15, objective = "Recover the two parts of the Scepter of Celebras: the Celebrian Rod and the Celebrian Diamond.\n\nFind a way to speak with Celebras.", npcs = { 12236, 13282 } }, -- Legends of Maraudon
  [7046] = { name = "The Scepter of Celebras", instance = 349, level = 49, prev = 7044, npc = "Celebras the Redeemed", npcID = 13716, rewards = { 17191 }, objective = "Assist Celebras the Redeemed while he creates the Scepter of Celebras.\n\nSpeak with him when the ritual is complete." }, -- The Scepter of Celebras
  [7064] = { name = "Corruption of Earth and Seed", instance = 349, level = 51, faction = "Horde", npc = "Selendra", npcID = 13699, map = 1443, x = 26.9, y = 77.7, cont = 1414, cx = 38.16, cy = 59.82, choices = { 17705, 17743, 17753 }, objective = "Slay Princess Theradras and return to Selendra near Shadowprey Village in Desolace.", npcs = { 12201 } }, -- Corruption of Earth and Seed
  [7065] = { name = "Corruption of Earth and Seed", instance = 349, level = 51, faction = "Alliance", npc = "Keeper Marandis", npcID = 13698, map = 1443, x = 63.8, y = 10.7, cont = 1414, cx = 42.67, cy = 51.63, choices = { 17705, 17743, 17753 }, objective = "Slay Princess Theradras and return to Keeper Marandis at Nijel's Point in Desolace.", npcs = { 12201 } }, -- Corruption of Earth and Seed
  [7066] = { name = "Seed of Life", instance = 349, level = 51, npc = "Zaetar's Spirit", npcID = 12238, objective = "Seek out Remulos in Moonglade and give him the Seed of Life." }, -- Seed of Life
  [7067] = { name = "The Pariah's Instructions", instance = 349, level = 48, npc = "Centaur Pariah", npcID = 13717, map = 1443, x = 50.4, y = 86.7, cont = 1414, cx = 41.03, cy = 60.92, rewards = { 17774 }, objective = "Read the Pariah's Instructions. Afterwards, obtain the Amulet of Union from Maraudon and return it to the Centaur Pariah in southern Desolace." }, -- The Pariah's Instructions
  [7068] = { name = "Shadowshard Fragments", instance = 349, level = 42, faction = "Horde", npc = "Uthel'nay", npcID = 7311, map = 1454, x = 39.2, y = 86.3, cont = 1414, cx = 57.87, cy = 46.19, choices = { 17772, 17773 }, objective = "Collect 10 Shadowshard Fragments from Maraudon and return them to Uthel'nay in Orgrimmar." }, -- Shadowshard Fragments
  [7070] = { name = "Shadowshard Fragments", instance = 349, level = 42, faction = "Alliance", npc = "Archmage Tervosh", npcID = 4967, map = 1445, x = 66.4, y = 49.3, cont = 1414, cx = 58.5, cy = 67.49, choices = { 17772, 17773 }, objective = "Collect 10 Shadowshard Fragments from Maraudon and return them to Archmage Tervosh in Theramore on the coast of Dustwallow Marsh." }, -- Shadowshard Fragments
  [7201] = { name = "The Last Element", instance = 230, level = 54, faction = "Horde", npc = "Shadowmage Vivian Lagrave", npcID = 9078, map = 1427, x = 81.9, y = 39.1, cont = 1415, cx = 51.57, cy = 60.29, rewards = { 12038 }, objective = "Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals.", npcs = { 8905, 8906, 8908, 8909, 8910, 8911, 8923, 9017, 9025, 9156 } }, -- The Last Element
  [7429] = { name = "Free Knot!", instance = 429, level = 60, prev = 5525, npc = "Knot Thimblejack", npcID = 14338, inside = true, npcs = { 11441, 11444, 11445, 11448, 11450, 14321, 14323, 14325, 14326 }, repeatable = true }, -- Free Knot!
  [7441] = { name = "Pusillin and the Elder Azj'Tordin", instance = 429, level = 58, npc = "Azj'Tordin", npcID = 14355, map = 1444, x = 76.9, y = 37.4, cont = 1414, cx = 46.11, cy = 68.87, choices = { 18411, 18410 }, objective = "Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary.\n\nReturn to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations.", npcs = { 14354 } }, -- Pusillin and the Elder Azj'Tordin
  [7461] = { name = "The Madness Within", instance = 429, level = 60, npc = "Shen'dralar Ancient", npcID = 14358, inside = true, objective = "You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.\n\nEnter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.\n\nReturn to the Shen'dralar Ancient in the courtyard should you complete this quest.", npcs = { 11486, 11496 } }, -- The Madness Within
  [7462] = { name = "The Treasure of the Shen'dralar", instance = 429, level = 60, faction = "Alliance", prev = 7461, npc = "Shen'dralar Ancient", npcID = 14358, inside = true, choices = { 18420, 18421, 18424 }, objective = "Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!" }, -- The Treasure of the Shen'dralar
  [7463] = { name = "Arcane Refreshment", instance = 429, level = 60, classes = { "MAGE" }, npc = "Lorekeeper Lydros", npcID = 14368, inside = true, objective = "Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence.", npcs = { 13280 } }, -- Arcane Refreshment
