  [7509] = { name = "The Forging of Quel'Serrar", instance = 249, level = 60, prev = 7508, npc = "Lorekeeper Lydros", npcID = 14368, rewards = { 18348 }, objective = "You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence.\n\nThe last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse.\n\nDo this and Quel'Serrar will be yours.", repeatable = true }, -- The Forging of Quel'Serrar
  [7581] = { name = "The Prison's Bindings", instance = 429, level = 60, classes = { "WARLOCK" }, npc = "Daio the Decrepit", npcID = 14463, map = 1419, x = 34.1, y = 50.1, cont = 1415, cx = 52.23, cy = 81.62, objective = "Travel to Dire Maul in Feralas and recover 15 Satyr Blood from the Wildspawn Satyr that inhabit the Warpwood Quarter. Return to Daio in the Tainted Scar when this is done.", npcs = { 11451, 11452, 11453, 11454, 11455, 11456, 11457 } }, -- The Prison's Bindings
  [7583] = { name = "Suppression", level = 60, classes = { "WARLOCK" }, prev = 7581, npc = "Daio the Decrepit", npcID = 14463, map = 1419, x = 34.1, y = 50.1, cont = 1415, cx = 52.23, cy = 81.62, rewards = { 18602 }, objective = "Venture forth into the Tainted Scar and locate a Doomguard Commander.\n\nUse the Glowing Crystal Prison on the Doomguard Commander. Be prepared for a ferocious onslaught of attacks, as the demon attempts to escape capture.\n\nShould you succeed, return the Imprisoned Doomguard to Daio in the Tainted Scar." }, -- Suppression
  [7604] = { name = "A Binding Contract", instance = 230, level = 60, inside = true, item = 18628, rewards = { 18592 }, objective = "Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron.", repeatable = true }, -- A Binding Contract
  [7703] = { name = "Unfinished Gordok Business", instance = 429, level = 60, npc = "Captain Kromcrush", npcID = 14325, inside = true, choices = { 18366, 18367, 18368, 18369 }, objective = "Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.\n\nAccording to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings." }, -- Unfinished Gordok Business
  [7761] = { name = "Blackhand's Command", instance = 229, level = 60, item = 18987, objective = "That is one stupid orc. It would appear as if you need to find this brand and gain the Mark of Drakkisath in order to access the Orb of Command.\n\nThe letter indicates that General Drakkisath guards the brand. Perhaps you should investigate." }, -- Blackhand's Command
