  [8733] = { name = "Eranikus, Tyrant of the Dream", instance = 109, level = 60, npc = "Malfurion Stormrage", npcID = 15362, objective = "Travel to the continent of Teldrassil and find Malfurion's agent somewhere outside the walls of Darnassus." }, -- Eranikus, Tyrant of the Dream
